/* particles.js — pool de partículas: faíscas, sangue, fogo, fumaça, muzzle flash.
 * 🎨 Render: sprites Three (Points) com vida curta, sem alocação por frame.
 * Dois sistemas de blend: aditivo (fogo/faíscas/muzzle) e normal (sangue/fumaça),
 * cada um com seu próprio pool. API pública preservada: sparks, blood, fire, smoke, update.
 */
import * as THREE from 'three';
import { C } from './constants.js';

const MAX = C.PARTICLES.max;

// Sprite suave (círculo radial) via canvas — opcional; sem document (Node/tests) fica quadrado.
function makeSprite() {
  if (typeof document === 'undefined') return null;
  const c = document.createElement('canvas');
  c.width = c.height = 32;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.85)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 32, 32);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const SPRITE = makeSprite();

function makeSystem(scene, { blending, opacity = 1 }) {
  const positions = new Float32Array(MAX * 3);
  const colors = new Float32Array(MAX * 3);
  const sizes = new Float32Array(MAX);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

  const mat = new THREE.PointsMaterial({
    size: 0.12,
    vertexColors: true,
    transparent: true,
    opacity,
    depthWrite: false,
    sizeAttenuation: true,
    blending,
    map: SPRITE || undefined,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  scene.add(points);

  const pool = [];
  for (let i = 0; i < MAX; i++) {
    pool.push({
      active: false,
      life: 0,
      maxLife: 1,
      vx: 0, vy: 0, vz: 0,
      r: 1, g: 1, b: 1,
      size: 0.1,
      grow: 0,
      gravity: 0,
      drag: 0,
    });
  }
  pool.forEach((p, i) => { p._i = i; });

  let cursor = 0;

  function emit(x, y, z, opts = {}) {
    const p = pool[cursor];
    cursor = (cursor + 1) % MAX;
    p.active = true;
    p.life = p.maxLife = opts.life ?? 0.5;
    p.vx = opts.vx ?? (Math.random() - 0.5) * 2;
    p.vy = opts.vy ?? Math.random() * 2;
    p.vz = opts.vz ?? (Math.random() - 0.5) * 2;
    p.r = opts.r ?? 1; p.g = opts.g ?? 1; p.b = opts.b ?? 1;
    p.size = opts.size ?? 0.1;
    p.grow = opts.grow ?? 0;      // expansão de tamanho ao longo da vida (opcional)
    p.gravity = opts.gravity ?? 0; // negativo = puxa para baixo
    p.drag = opts.drag ?? 0;       // amortecimento de velocidade por segundo (0..1 retido)
    positions[p._i * 3] = x;
    positions[p._i * 3 + 1] = y;
    positions[p._i * 3 + 2] = z;
  }

  function update(dt) {
    for (const p of pool) {
      if (!p.active) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        positions[p._i * 3 + 1] = -999;
        continue;
      }
      p.vy += p.gravity * dt;
      if (p.drag > 0) {
        const d = Math.max(0, 1 - p.drag * dt);
        p.vx *= d; p.vy *= d; p.vz *= d;
      }
      positions[p._i * 3] += p.vx * dt;
      positions[p._i * 3 + 1] += p.vy * dt;
      positions[p._i * 3 + 2] += p.vz * dt;
      const fade = p.life / p.maxLife;
      colors[p._i * 3] = p.r * fade;
      colors[p._i * 3 + 1] = p.g * fade;
      colors[p._i * 3 + 2] = p.b * fade;
      sizes[p._i] = p.size + p.grow * (1 - fade);
    }
    geo.attributes.position.needsUpdate = true;
    geo.attributes.color.needsUpdate = true;
    geo.attributes.size.needsUpdate = true;
  }

  return { emit, update };
}

export function createParticles(scene) {
  const additive = makeSystem(scene, { blending: THREE.AdditiveBlending });
  const normal = makeSystem(scene, { blending: THREE.NormalBlending, opacity: 0.85 });

  function sparks(x, y, z, n = 6, color = 0xffcc44) {
    const c = new THREE.Color(color);
    for (let i = 0; i < n; i++) {
      additive.emit(x, y, z, {
        life: 0.3 + Math.random() * 0.3,
        vx: (Math.random() - 0.5) * 6,
        vy: Math.random() * 4,
        vz: (Math.random() - 0.5) * 6,
        r: c.r, g: c.g, b: c.b,
        size: 0.06,
        gravity: -6,
      });
    }
  }

  function blood(x, y, z, n = 8) {
    for (let i = 0; i < n; i++) {
      normal.emit(x, y, z, {
        life: 0.4 + Math.random() * 0.4,
        vx: (Math.random() - 0.5) * 3,
        vy: Math.random() * 2.5,
        vz: (Math.random() - 0.5) * 3,
        r: 0.7, g: 0.05, b: 0.05,
        size: 0.09,
        gravity: -8,
      });
    }
  }

  function fire(x, y, z, n = 10) {
    for (let i = 0; i < n; i++) {
      const t = Math.random();
      additive.emit(x, y, z, {
        life: 0.3 + Math.random() * 0.4,
        vx: (Math.random() - 0.5) * 1.5,
        vy: 2 + Math.random() * 2,
        vz: (Math.random() - 0.5) * 1.5,
        r: 1, g: 0.5 + t * 0.4, b: 0.1,
        size: 0.15,
        gravity: 0,
      });
    }
  }

  function smoke(x, y, z, n = 6) {
    for (let i = 0; i < n; i++) {
      normal.emit(x, y, z, {
        life: 0.8 + Math.random() * 0.6,
        vx: (Math.random() - 0.5) * 1,
        vy: 1.5 + Math.random() * 1.5,
        vz: (Math.random() - 0.5) * 1,
        r: 0.4, g: 0.4, b: 0.42,
        size: 0.22,
        grow: 0.5,   // expande enquanto sobe
        gravity: 0,
        drag: 0.6,   // desacelera suavemente
      });
    }
  }

  function muzzle(x, y, z, n = 8) {
    for (let i = 0; i < n; i++) {
      additive.emit(x, y, z, {
        life: 0.08 + Math.random() * 0.1,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        vz: (Math.random() - 0.5) * 8,
        r: 1, g: 0.7 + Math.random() * 0.3, b: 0.2,
        size: 0.07,
        gravity: 0,
        drag: 2,
      });
    }
  }

  function update(dt) {
    additive.update(dt);
    normal.update(dt);
  }

  return { sparks, blood, fire, smoke, muzzle, update };
}

export default createParticles;

