import { createPickups, updatePickups } from './pickups.js';
import assert from 'node:assert/strict';

const scene = {
  children: [],
  add(m) { this.children.push(m); },
  remove(m) { const i = this.children.indexOf(m); if (i >= 0) this.children.splice(i, 1); },
};
const map = { pickups: [
  { type: 'health', x: 1, z: 1, taken: false },
  { type: 'armor', x: 2, z: 2, taken: false },
  { type: 'shotgun', x: 3, z: 3, taken: false },
  { type: 'ammo', x: 4, z: 4, taken: false },
  { type: 'bullet', x: 5, z: 5, taken: false },
] };

const pks = createPickups(scene, map);
assert.equal(pks.length, 5);
assert.equal(scene.children.length, 5);
assert.deepEqual(pks.map((p) => p.cat), ['health', 'armor', 'weapon', 'ammo', 'ammo']);
assert.ok(pks.every((p) => typeof p.id === 'number' && p.mesh && p.baseY === 0.5 && typeof p.phase === 'number'));
assert.ok(pks.every((p) => typeof p.type === 'string'), 'original fields preserved');
const phases = new Set(pks.map((p) => p.phase));
assert.ok(phases.size > 1, 'phases desync deterministically');

// bobbing moves y over time; no collection far away
const before = pks[0].mesh.position.y;
const far = updatePickups(pks, 0.016, 999, 999, 0.9, () => assert.fail('nothing in range'));
assert.notEqual(pks[0].mesh.position.y, before, 'bobbing applied');
assert.equal(far.length, 5);
assert.ok(pks.every((p) => !p.collected));

// collect health: player at (1,1), radius 0.9
let got = null;
const after = updatePickups(pks, 0.016, 1, 1, 0.9, (p) => { got = p; });
assert.equal(got.cat, 'health');
assert.equal(got.id, 0);
assert.equal(after.length, 4);
assert.equal(scene.children.length, 4, 'mesh removed from scene');
assert.ok(pks[0].collected, 'collected flag set');
assert.ok(!after.some((p) => p.id === 0), 'filtered out');

// collected pickup does not re-collect / remaining ones still animated
const again = updatePickups(after, 0.016, 999, 999, 0.9, () => assert.fail('nothing left'));
assert.equal(again.length, 4);

// two pickups both in range -> both collected
const p2 = createPickups(scene, { pickups: [{ type: 'rocket', x: 0, z: 0 }, { type: 'chaingun', x: 0.1, z: 0.1 }] });
let count = 0;
const res2 = updatePickups(p2, 0.016, 0, 0, 0.9, () => { count++; });
assert.equal(count, 2);
assert.equal(res2.length, 0);

console.log('PICKUP SMOKE OK');

