  assert.equal(typeof p.smoke, 'function');
  assert.equal(typeof p.muzzle, 'function');
  assert.equal(typeof p.update, 'function');
  p.sparks(0, 0, 0, 4, 0xffcc44);
  p.blood(0, 1, 0, 6);
  p.fire(0, 2, 0, 8);
